import {escapeLab} from './catalog-labs.js?v=20261023-physicscomplete01';
const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-family="sans-serif" font-size="${size}">${escapeLab(s)}</text>`;
export function catalogArt(v={kind:'flow',nodes:['Observe','Predict','Test']}){if(v.kind==='table')return '<div class="catalog-data"><table class="aqueous-observations"><caption>Supplied evidence</caption><thead><tr>'+v.columns.map(c=>'<th>'+escapeLab(c)+'</th>').join('')+'</tr></thead><tbody>'+v.rows.map(r=>'<tr>'+r.map(c=>'<td>'+escapeLab(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
let art='',desc='';if(v.kind==='bars'){const bars=v.bars||[],max=Math.max(1,...bars.map(b=>Number(b.value)));desc=bars.map(b=>b.label+':'+b.value).join('; ');art=bars.map((b,i)=>{const x=60+i*330/Math.max(1,bars.length),width=Math.min(45,240/Math.max(1,bars.length)),h=Number(b.value)/max*150;return `<rect x="${x}" y="${205-h}" width="${width}" height="${h}" rx="4" fill="${i%2?'#b7c8d6':'#ed8b78'}"/>${txt(x+width/2,190-h,b.value,14)}${txt(x+width/2,230,b.label,12)}`;}).join('');}else if(v.kind==='molecule'){const atoms=v.atoms||[],pos=atoms.map((_,i)=>[55+(i%6)*65,80+Math.floor(i/6)*85]);desc='Symbolic structure. Atoms: '+atoms.join(', ')+'. Bonds connect '+(v.bonds||[]).map(b=>b[0]+' to '+b[1]).join('; ');art='<defs><radialGradient id="catalogAtom" cx=".3" cy=".25"><stop stop-color="#f8f6f2"/><stop offset=".4" stop-color="#ed8b78"/><stop offset="1" stop-color="#a76657"/></radialGradient></defs>'+(v.bonds||[]).map(([a,b,order=1])=>{if(!pos[a]||!pos[b])return '';return Array.from({length:order},(_,j)=>`<path d="M${pos[a][0]} ${pos[a][1]+(j-(order-1)/2)*5}L${pos[b][0]} ${pos[b][1]+(j-(order-1)/2)*5}" stroke="#b7c8d6" stroke-width="3"/>`).join('');}).join('')+atoms.map((a,i)=>`<circle cx="${pos[i][0]}" cy="${pos[i][1]}" r="22" fill="url(#catalogAtom)"/>${txt(pos[i][0],pos[i][1]+5,a,15)}`).join('');}else{const nodes=v.nodes||['Observe','Predict','Check'];desc=nodes.join(' → ');const n=nodes.length;art=nodes.map((s,i)=>{const y=35+i*225/Math.max(1,n);const words=String(s).split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).length>34){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return `<rect x="35" y="${y}" width="370" height="${Math.min(62,210/n)}" rx="12" fill="#b7c8d622" stroke="#b7c8d6"/>${lines.slice(0,2).map((l,j)=>txt(220,y+22+j*18,l,15)).join('')}${i<n-1?`<path d="M220 ${y+Math.min(62,210/n)}v8" stroke="#ed8b78" stroke-width="3"/>`:''}`;}).join('');}
return `<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${escapeLab(desc)}">${art}</svg>`;}
